template <class Derived>
struct Shape {
    double area() const { return static_cast<const Derived*>(this)->areaImpl(); }
};
struct Circle : Shape<Circle> {
    double r;
    double areaImpl() const { return 3.14159265 * r * r; }
};
template <class S> double total(const std::vector<S>& v);   // one instantiation per shape

template <class Derived>
struct Shape {
    double area() const { return static_cast<const Derived*>(this)->areaImpl(); }
};
template <class Derived> requires std::derived_from<Derived, Shape<Derived>>
double total(const std::vector<Derived>& v);   // contract stated where it is checked

struct ShapeBase {
    template <class Self>
    double area(this const Self& self) { return self.areaImpl(); }
};
struct Circle : ShapeBase {
    double r;
    double areaImpl() const { return 3.14159265 * r * r; }
};

